E="الموسوعة الفقهية الكويتية، ج43 (مدخل وضوء)، https://shamela.ws/book/11430bu/"
def U(*ids): return "الموسوعة الفقهية الكويتية ج43، صفحات الشاملة: "+" ".join("https://shamela.ws/book/11430bu/%d"%i for i in ids)
DUA="الدعاء عند العضو:: استحبه الحنفية والمالكية (ذكر الله) وأكثر الشافعية وجماعة من الحنابلة كما في الموسوعة، وصيغه المنقولة تُذكر هنا بلفظ الموسوعة.\nمدى ثبوتها:: قال النووي في الأذكار: «وأما الدعاء على أعضاء الوضوء فلم يجئ فيه شيء عن النبي ﷺ، وقد قال الفقهاء: يستحب فيه دعوات جاءت عن السلف». وفي حاشية محقق الأذكار أن النووي قال في الروضة «لا أصل له»، وأن الإسنوي تعقبه بأنه روي من طرق منها حديث أنس في تاريخ ابن حبان، وأن المحقق عدّ ذلك الحديث من الواهي الشديد الضعف. ونقلت الموسوعة عن ابن عابدين أن الوارد منه تقوي طرقه بعضها بعضاً فيرتقي إلى الحسن، وهذا قول عام عن الباب، ولم يُدرس هنا إسناد أي صيغة بعينها، فلا يُنسب أي لفظ منها إلى النبي ﷺ. تُقرأ الصيغ على أنها دعاء استحبه من استحبه، وليست سنة ثابتة بنص.\n"
DUA0=DUA.split("\n")[0]+"\n"
DUAS="مدى ثبوتها:: لم يثبت لفظ هذا الدعاء عن النبي ﷺ عند النووي في الأذكار، ولم يُدرس هنا إسناد أي صيغة. والتفصيل في خطوة غسل الكفين.\n"
DN="لا ذكر ثابت عن النبي ﷺ عند هذا العضو بحسب ما قُرئ هنا. والدعاء المذكور أعلاه مستحب عند من استحبه، ولم يثبت لفظه بنص."
NAW=" الأذكار للنووي (فصل أدعية أعضاء الوضوء): https://shamela.ws/book/10639/90"
def mk(n,name,action,dhikr,whisper,ref,exact=False,none=True):
    d={"n":n,"name":name,"action":action,"dhikr":dhikr,"whisper":whisper,"ref":ref}
    if none: d["dhikrNone"]=True
    if exact: d["dhikrExact"]=True
    return d
old={s['n']:s for s in L['steps']}
steps=[
mk(1,"النية","النية بالقلب قبل بدء الوضوء.\nحكمها:: عند الشافعية والحنابلة شرط في صحة الوضوء فلا يصح إلا بها. وعند الحنفية سنة، ليقع قربة وليخرج من عهدة الفرض. وعند المالكية فرض (وفي رواية عن مالك بعدم الوجوب).\nالتلفظ بها:: عند الشافعية التلفظ بالنية سنة، وتقرن عند أول غسل الكفين بالتسمية. ولم تفصل الصفحات المقروءة قول بقية المذاهب في التلفظ.\nرفضها:: إذا رفض المتوضئ النية بعد تمام الوضوء لم يؤثر ذلك عند المالكية والشافعية والحنابلة على الصحيح. وإذا نوى قطعه في أثنائه: الشافعية في الأصح لا يبطل ويستأنف النية لما بقي، والحنابلة في الصحيح يبطل ما مضى، والمالكية على الراجح يبطل.",
 "النية عمل القلب، ولا يُذكر هنا لفظ مخصوص لها.",old[1]['whisper'],"الموسوعة، النية في الوضوء (ج42): https://shamela.ws/book/11430bu/27609 https://shamela.ws/book/11430bu/27610 https://shamela.ws/book/11430bu/27611 | "+U(28871,28872,28879)+""),
mk(2,"التسمية","قل «بسم الله» عند أول الوضوء.\nحكمها:: سنة عند الحنفية والشافعية وفي رواية عن أحمد، ومستحبة عند المالكية على المشهور (وقيل: غير مشروعة وتكره)، وواجبة عند الحنابلة.\nالصيغة:: عند الحنابلة «بسم الله» ولا يقوم غيرها مقامها على الأشهر، ومحلها اللسان. وعند الشافعية أقلها «بسم الله» وأكملها «بسم الله الرحمن الرحيم». وعند المالكية «بسم الله» وفي زيادة «الرحمن الرحيم» قولان. وعند الحنفية يحصل أصل السنة بكل ذكر، والمنقول عن السلف «بسم الله العظيم، والحمد لله على الإسلام».\nوقتها:: عند أول غسل الكفين، وعند الحنابلة وقتها عند أول الواجبات وجوباً وأول المسنونات استحباباً.\nعند كل عضو:: من آداب الوضوء عند الحنفية التسمية عند غسل كل عضو، وظاهر كلام فقهاء الحنابلة أنها لا تستحب عند كل عضو.",
 "بِسْمِ اللَّهِ",old[2]['whisper'],"الموسوعة، ج43 ص358-359: "+U(28879,28880,28881)+"؛ أبو داود (101)، وفي ثبوت حديث التسمية خلاف (انظر جدول الخلاف)",exact=True,none=False),
mk(3,"غسل الكفين","اغسل كفيك إلى الرسغين في بداية الوضوء.\nحكمه:: ذهب الفقهاء إلى أن غسل اليدين الطاهرتين إلى الرسغين في ابتداء الوضوء سنة، لفعل النبي ﷺ في حديث عثمان (كما نقلت الموسوعة، وغير مدروس هنا). وإن كانتا نجستين وجب غسلهما اتفاقاً.\nالعدد:: تثليث غسل الأعضاء سنة عند الفقهاء، والموسوعة تنقل أنه ﷺ توضأ مرة مرة ومرتين مرتين وثلاثاً ثلاثاً (غير مدروس هنا).\n"+DUA+"وليس في الصفحات المقروءة دعاء مخصوص عند غسل الكفين.",
 DN,old[3]['whisper'],"الموسوعة، ج43: "+U(28882,28896)+""),
mk(4,"المضمضة والاستنشاق","تمضمض واستنشق واستنثر.\nالمضمضة والاستنشاق:: سنتان عند جمهور الفقهاء، وواجبتان (فرض) عند الحنابلة.\nالاستنثار:: سنة عند الحنفية والمالكية والشافعية والحنابلة لحديث «إذا استنشقت فانتثر» (كما في تخريج الموسوعة، وغير مدروس هنا). وعند المالكية طرح الماء من الأنف بالنفس واضعاً السبابة والإبهام من اليد اليسرى عليه، وعند الشافعية يخرج ما في أنفه بخنصر يده اليسرى، وعند الحنابلة يسن استنثاره بيساره.\n"+DUA0+DUAS+"عند المضمضة: «اللهم أعني على تلاوة القرآن الكريم وذكرك وشكرك وحسن عبادتك»، وعند الاستنشاق: «اللهم أرحني رائحة الجنة ولا ترحني رائحة النار».",
 DN,old[4]['whisper'],"الموسوعة، ج43: "+U(28883,28884,28911,28912)+NAW+""),
mk(5,"غسل الوجه","اغسل وجهك، والواجب غسل ظاهره كله مرة.\nالحد:: عرضاً ما بين الأذنين، وطولاً من منابت شعر الرأس إلى أسفل الذقن، وعند المالكية والحنابلة فيمن له لحية إلى منتهى لحيته.\nالمجزئ من الغسل:: يكفي جريان الماء ولا يشترط الدلك عند الحنفية والشافعية والحنابلة، وانفرد مالك والمزني باشتراطه (انظر جدول الخلاف).\nالشعر الخفيف (الذي تبدو البشرة من خلاله):: يجب غسله ظاهراً وباطناً حتى البشرة عند الحنفية والشافعية، وعند المالكية يجب تخليله. ولم تُقرأ هنا عبارة الحنابلة في الخفيف.\nالشعر الكثيف:: الحنفية لا يجب غسل أصوله ويسن تخليل لحية غير المحرم. المالكية يكره تخليله ويجب تحريكه ليدخل الماء بين ظاهره. الشافعية في لحية الرجل الكثيفة يغسل ظاهرها ولا يجب باطنها ويسن تخليلها، أما الحاجب والشارب والعنفقة فيجب غسلها ظاهراً وباطناً. الحنابلة يجب غسل ظاهر اللحية ويسن غسل باطنها.\nالمسترسل من اللحية:: لا يجب غسله عند الحنفية، ويجب عند الحنابلة في الصحيح.\n"+DUA0+DUAS+"عند غسل الوجه: «اللهم بيض وجهي يوم تبيض وجوه وتسود وجوه».",
 DN,old[5]['whisper'],"الموسوعة، ج43: "+U(28827,28828,28829,28830,28911)+NAW+"؛ المائدة: 6"),
mk(6,"غسل اليدين إلى المرفقين","اغسل يدك اليمنى ثم اليسرى مع المرفقين.\nالمرفقان:: يجب غسلهما مع اليدين عند جمهور الفقهاء (المالكية والشافعية والحنابلة في المذهب والحنفية ما عدا زفر)، لقوله تعالى ﴿وأيديكم إلى المرافق﴾ ولحديث جابر «كان النبي ﷺ إذا توضأ أدار الماء إلى مرفقيه» (كما نقلت الموسوعة، وغير مدروس هنا).\nالبدء باليمنى:: التيامن سنة عند الشافعية وبعض الحنفية، وفي رواية عن أحمد واجب، ونقل ابن قدامة الإجماع على أنه لا إعادة على من بدأ بيساره قبل يمينه.\n"+DUA0+DUAS+"عند غسل اليد اليمنى: «اللهم أعطني كتابي بيميني وحاسبني حساباً يسيراً»، وعند اليسرى: «اللهم لا تعطني كتابي بشمالي ولا من وراء ظهري».",
 DN,old[6]['whisper'],"الموسوعة، ج43: "+U(28845,28899,28900,28911)+NAW+"؛ المائدة: 6"),
mk(7,"مسح الرأس","بلّ يديك وامسح رأسك، والمسح هو إمرار اليد المبتلة بلا تسييل.\nحكمه:: اتفق الفقهاء على أن مسح الرأس من أركان الوضوء أو فروضه.\nالقدر المجزئ:: المالكية على المشهور: الرأس كله من منابت الشعر إلى نقرة القفا (وقال أشهب يكفي النصف، وقيل الثلثان أو الثلث). الحنابلة في الصحيح: جميع ظاهر الرأس (وعن أحمد: أكثره، وعنه قدر الناصية). الحنفية: الأشهر ربع الرأس وهو المعتمد، وقيل مقدار الناصية، وقيل ثلاثة أصابع. الشافعية: مسمى المسح ولو بعض شعرة.\nبماذا يمسح:: عند الحنفية على الأصح بثلاثة أصابع، وعند الحنابلة على أي كيفية، حتى بحائل.\nمسح الأذنين:: سنة عند الحنفية والمالكية على المشهور والشافعية، ظاهرهما وباطنهما، لأن النبي ﷺ مسح برأسه وأذنيه ظاهرهما وباطنهما (كما نقلت الموسوعة، وغير مدروس هنا).\n"+DUA0+DUAS+"عند مسح الرأس: «اللهم أظلني تحت عرشك يوم لا ظل إلا ظل عرشك»، وعند مسح الأذنين: «اللهم اجعلني من الذين يستمعون القول فيتبعون أحسنه».",
 DN,old[7]['whisper'],"الموسوعة، ج43: "+U(28859,28860,28861,28891,28911)+NAW+"؛ المائدة: 6",),
mk(8,"غسل الرجلين إلى الكعبين","اغسل رجلك اليمنى ثم اليسرى مع الكعبين، وخلّل بين الأصابع، واحرص على العقبين.\nحكمه:: غسل الرجلين الظاهرتين السليمتين (غير المستورتين بخف أو جبيرة) إلى الكعبين مرة ركن من أركان الوضوء عند الحنفية والمالكية والشافعية والحنابلة. والكعبان هما العظمان الناتئان في أسفل الساق، وخالف زفر في دخولهما كما خالف في المرفقين.\nالدليل:: قوله تعالى ﴿وأرجلكم إلى الكعبين﴾، وأمره ﷺ بتخليل الأصابع وأنه كان يدلك بخنصره ما بين أصابع رجليه (كما نقلت الموسوعة، وغير مدروس هنا).\nالعقبان:: ذكرت الموسوعة في الدلك عند الشافعية حديث «ويل للأعقاب من النار» (كما في تخريج الموسوعة، وغير مدروس هنا)، وأن الشافعية يبالغون في العقب خصوصاً في الشتاء.\n"+DUA0+DUAS+"عند غسل الرجل اليمنى: «اللهم ثبت قدمي على الصراط يوم تزل الأقدام»، وعند اليسرى: «اللهم اجعل ذنبي مغفوراً وسعيي مشكوراً وتجارتي لن تبور».",
 DN,old[8]['whisper'],"الموسوعة، ج43: "+U(28866,28867,28868,28869,28877,28911)+NAW+"؛ المائدة: 6"),
]
