for k in L['khilaf']:
    if k['id']=='k9':
        k['v']={"hanafi":"لا ينقض. ويغسل يده ندباً.","maliki":"ينقض مس الرجل ذكره هو (متصلاً) ببطن الكف أو جنبه أو الإصبع، ولا يشترط قصد ولا لذة. ومس ذكر غيره كحكم اللمس (يشترط قصد اللذة أو وجودها). والمرأة لا ينقض مسها فرجها إلا إن قبضت عليه أو أدخلت يدها بين الشفرين.","shafii":"ينقض مس قبل الآدمي (ذكراً أو أنثى، من نفسه أو غيره) ببطن الكف بلا حائل، وكذا حلقة الدبر في الجديد. ولا ينقض برأس الأصابع وما بينها.","hanbali":"في الرواية التي تجعله حدثاً: ينقض مس ذكر الآدمي إلى أصول الأنثيين، ومس حلقة الدبر، ومس المرأة فرجها بين الشفرين، بباطن اليد أو ظهرها أو حرفها بلا حائل، بشهوة أو بغيرها. وفي رواية أخرى: لا ينقض."}
        k['note']="المصدر: الموسوعة الفقهية الكويتية: https://shamela.ws/book/11430bu/10219 و https://shamela.ws/book/11430bu/10220 و https://shamela.ws/book/11430bu/10221 و https://shamela.ws/book/11430bu/20254 و https://shamela.ws/book/11430bu/20255 و https://shamela.ws/book/11430bu/20256 . هذا ما ورد في هذه المواضع، وما لم يرد فيها لم يُنسب لمذهب." 
    if k['id']=='k11':
        k['issue']='الدم والقيء ونحوهما من غير السبيلين'
        k['v']={"hanafi":"الدم والصديد: ينقضان إذا سالا عن موضعهما (وعند زفر ينقض ولو لم يسل). القيء: ينقض إذا كان ملء الفم، أي لا ينطبق عليه الفم إلا بتكلف في الأصح (وقيل: ما يمنع الكلام)، والمتفرق يجمع إن كان بسبب واحد. وما دون ملء الفم لا ينقض.","maliki":"لا ينقض الدم ولا القيح ولا القيء.","shafii":"لا ينقض القيء، ولا ينقض خروج النجاسة من غير السبيلين، ويجب تطهير الموضع.","hanbali":"ينقض الكثير من القيء والدم والقيح دون اليسير. والكثير ما فحش في نفس كل أحد بحسبه."}
        k['note']="المصدر: الموسوعة الفقهية الكويتية: عام (ج43): https://shamela.ws/book/11430bu/28935 . الدم والصديد عند الحنفية: https://shamela.ws/book/11430bu/16556 و https://shamela.ws/book/11430bu/13673 . القيء: https://shamela.ws/book/11430bu/21621 و https://shamela.ws/book/11430bu/21622 . الحنابلة (الكثير): https://shamela.ws/book/11430bu/10205 و https://shamela.ws/book/11430bu/21623 و https://shamela.ws/book/11430bu/21704 . وحديث «قاء فتوضأ» وقول ابن عباس في الفاحش منقولان عن الموسوعة وغير مدروسين هنا. وغير مغطى هنا: تعريف الحنفية لموضع السيلان، وتفصيل الحنابلة في روايات مقدار الدم والقيء."
    if k['id']=='k8':
        k['v']={"hanafi":"لا ينقض (ويرى أبو حنيفة وأبو يوسف أن المباشرة الفاحشة حدث استحساناً، وخالف محمد).","maliki":"ينقض لمس البالغ لمن يلتذ به عادة إن قصد اللذة أو وجدها.","shafii":"ينقض التقاء بشرتي الرجل والمرأة الأجنبية التي تشتهى، بشهوة أو بغير شهوة.","hanbali":"ينقض إن كان بشهوة، ولا ينقض بغير شهوة في المشهور (وفي رواية: لا ينقض)."}
        k['note']="المصدر: الموسوعة الفقهية الكويتية، لمس (ج35 ص332): https://shamela.ws/book/11430bu/22742 و https://shamela.ws/book/11430bu/22743 و https://shamela.ws/book/11430bu/22744 ؛ وشهوة (ج26 ص265-266): https://shamela.ws/book/11430bu/16396 . وفي نقض وضوء الملموس عند الشافعية قولان مشهوران. وسبب الخلاف معنى «اللمس» في الآية، لم يُدرس هنا."
    if k['id']=='k9_old':
        k['v']={"hanafi":"لا ينقض، ويُغسل اليد ندباً.","maliki":"ينقض مس الفرج بالكف في الجملة بلا حائل.","shafii":"ينقض مس الفرج بالكف في الجملة بلا حائل.","hanbali":"ينقض في الجملة (وفي رواية أخرى: لا ينقض)."}
        k['note']="المصدر: الموسوعة الفقهية الكويتية، الوضوء من مس الفرج (ج32 ص85): https://shamela.ws/book/11430bu/20254 ؛ ومس فرج الآدمي (ج17 ص119): https://shamela.ws/book/11430bu/10221 . تفاصيل الشروط عند كل مذهب (باطن الكف أو الأصابع وغيرهما) لم تُقرأ هنا."
